/* 按绝对时间片等待下一个节拍。用累加的绝对时刻而不是 HAL_Delay，
 * 避免每帧多出来的执行时间累积成漂移。 */
static void cross_wait_next_tick(uint32_t *next_ms)
{
    *next_ms += CROSS_OUTPUT_PERIOD_MS;
    while ((int32_t)(HAL_GetTick() - *next_ms) < 0) {
    }
}

void Cross_Play(float time_scale, uint32_t loops)
{
    float    target[CROSS_JOINT_COUNT];
    float    step;
    uint32_t ticks;
    uint32_t loop;
    uint32_t next_ms;

    if (!isfinite(time_scale) || (time_scale <= 0.0f) || (loops == 0U)) {
        return;
    }

    /* 一条轨迹切成多少个 20ms 节拍：倍数越大节拍越多、整体越慢。
     * step 保证帧位置正好覆盖 0~38 一整圈，不受取整误差影响。 */
    ticks = (uint32_t)((float)CROSS_FRAME_COUNT * time_scale + 0.5f);
    if (ticks == 0U) {
        ticks = 1U;
    }
    step = (float)CROSS_FRAME_COUNT / (float)ticks;

    next_ms = HAL_GetTick();

    for (loop = 0U; loop < loops; ++loop) {
        uint32_t tick;

        for (tick = 0U; tick < ticks; ++tick) {
            /* 0 ~ 38 之间的小数，表示走到轨迹的第几帧 */
            float    frame_pos = (float)tick * step;
            uint32_t index     = (uint32_t)frame_pos;
            float    frac      = frame_pos - (float)index;
            uint8_t  joint;

            /* 线性插值。time_scale = 1 时 frac 恒为 0，等于原样播放。 */
            for (joint = 0U; joint < CROSS_JOINT_COUNT; ++joint) {
                float a = cross_frames[index][joint];
                float b = cross_frames[(index + 1U) % CROSS_FRAME_COUNT][joint];
                target[joint] = a + ((b - a) * frac);
            }

            /* 和 Nano 指令走同一条路径：符号翻转 + 前倾 + roll 偏置 + 限位 */
            JetsonRobotBridge_ApplyModelTargets(target);

            cross_wait_next_tick(&next_ms);
        }
    }
}
